T("14章の追記：MIO（CVT）にはドライブモードを出さない（×0.9 のまま・切りかえられない）",`newRunState("AT","YUKI",[],null,{night:1});startBattleState("kei");G.char="MIO";startPlayerTurn(false);return{on:driveOn(),m:atMultNow(),can:canDrive(),set:setDrive("sport")}`,r=>!r.on&&r.m===0.9&&!r.can&&!r.set);

T("LD 11-65：HINA のスポーツは ×0.9（エコ ×0.85 はそのまま・YUKI のスポーツは ×1.0）",`const o={};for(const c of ["HINA","YUKI"]){newRunState("AT",c,[],null,{night:1});startBattleState("kei");startPlayerTurn(false);const e=atMultNow();setDrive("sport");o[c]=[e,atMultNow()]}return o`,r=>r.HINA[0]===0.85&&r.HINA[1]===0.9&&r.YUKI[0]===0.85&&r.YUKI[1]===1);

T("LD 11-65①：MOMO のエコはガソリンの最大 +0（×0.85 のまま）・YUKI のエコは +1",`const o={};for(const c of ["MOMO","YUKI"]){newRunState("AT",c,[],null,{night:1});startBattleState("kei");startPlayerTurn(false);o[c]=[atMultNow(),maxGas(),RULES.gasMax]}return o`,r=>r.MOMO[0]===0.85&&r.MOMO[1]===r.MOMO[2]&&r.YUKI[1]===r.YUKI[2]+1);

T("design 22章：starter＝初期デッキのキャラの一覧（CHARS[c].deck とそろう・ほかのカードには付かない）",`let bad=[];for(const c of Object.keys(CHARS)){const ids=new Set(CHARS[c].deck.map(x=>x[0]));for(const id of Object.keys(CARDS)){const has=(CARDS[id].starter||[]).includes(c);if(has!==ids.has(id))bad.push(c+":"+id)}}return bad`,r=>r.length===0);

T("design 10-16-2：弱点ギア（帯の範囲・×1.3・見つける前は予告にふくめない・形ごと）",`const R={};R.rng=[[5,"low"],[5,"mid"],[5,"high"],[6,"low"],[6,"mid"],[6,"high"],[8,"low"],[8,"mid"],[8,"high"]].map(([n,k])=>weakRange(k,n).join("-"));
 newRunState("MT","YUKI",[],null,{night:1});G.weakSeen={};startBattleState("boss1");startPlayerTurn(false);B.gear=0;R.mul1=weakMul();B.gear=4;R.mul5=weakMul();
 B.sim=true;G.weakSeen={};B.gear=0;R.simUnknown=weakMul();G.weakSeen[weakKey()]=1;R.simKnown=weakMul();B.sim=false;
 startBattleState("boss3");R.f=[0,1,2].map(i=>{B.e.mi=i;return weakOf()});R.k=[0,1].map(i=>{B.e.mi=i;return weakKey()});return R`,
 r=>r.rng.join()==="1-2,3-3,4-5,1-2,3-4,5-6,1-3,4-6,7-8"&&r.mul1===1.3&&r.mul5===1&&r.simUnknown===1&&r.simKnown===1.3&&r.f.join()==="high,mid,low"&&r.k[0]!==r.k[1]);

/* ★v0.22.102 奥義（design 10-15） */
const OGP=(ch,id,pre,o)=>SET(ch,[id,"hyouga"],o)+`B.rpm=1000;B.gear=0;${pre||""};const hp0=B.e.hp,blk0=B.block;B.ev=[];playCard(0,false);const d=hp0-B.e.hp;`;
T("10-15 白魔：凍結の合計 ×2（最大 80・倍率なし）・敵の番が1回おくれる・1戦に1回（除外）",OGP("YUKI","y_og_frz","B.frozeTotal=50;B.gear=5;const n0=B.e.next")+`return{d,del:Math.round(B.e.next-n0),disc:B.disc.some(c=>c.id==="y_og_frz"),hand:B.hand.length}`,r=>r.d===80&&r.del>0&&!r.disc);
T("10-15 白猫一閃：防御 15 を得て、防御 ×1.5（最大 90）",OGP("YUKI","y_og_cnt","B.block=10")+`return{d,b:B.block}`,r=>r.d===Math.min(90,Math.round(25*1.5))&&r.b===25);
T("10-15 緋雪閃：レッドの外は半分・打ったあと回転はレッド",OGP("YUKI","y_og_red")+`return{d,rpm:B.rpm,red:redLo()}`,r=>r.d===15&&r.rpm>=r.red);
T("10-15 暁天突破：40・3ターン目から半分",OGP("HINA","h_og_rush")+`const a=d;${SET("HINA",["h_og_rush"])}B.pTurns=2;B.rpm=1000;B.gear=0;const h1=B.e.hp;playCard(0,false);return[a,h1-B.e.hp]`,r=>r[0]===40&&r[1]===20);
T("10-15 陽炎百連：5 ×（このターンのアタック＋2）・最大 10回",OGP("HINA","h_og_combo","B.atks=3")+`return{d,hits:B.ev.filter(x=>x.k==="ehit").length}`,r=>r.hits===5&&r.d===25);
T("10-15 日向の盾：耐久 +15・防御 15・次の番の終わりまで半分",OGP("HINA","h_og_pit","G.hp=30")+`return{hp:G.hp,b:B.block,t:B.ogHalfT,p:B.pTurns}`,r=>r.hp===45&&r.b===15&&r.t===r.p+1);
T("10-15 百花繚乱：チェイン ×6（チェインの倍率もかかる）",OGP("MOMO","m_og_chain","B.chain=4")+`return{d,ch:B.chain}`,r=>r.d>=30&&r.ch===5);
T("10-15 花霞：防御＝チェイン ×3（最大 36）・このあとのガソリン −1",OGP("MOMO","m_og_guard","B.chain=5")+`const g=gasOf(B.hand[0]),g0=gasBase(B.hand[0]);return{b:B.block,g,g0}`,r=>r.b===18&&r.g===r.g0-1);
T("10-15 狂い咲き：失った耐久 ×1（最大 60）・半分以下で ×1.5",OGP("MOMO","m_og_rev","G.hp=20")+`return{d,mx:G.maxhp}`,r=>r.d===Math.round(Math.min(60,r.mx-20)*1.5));
T("10-15 千里鳳翔：このターンのシフト ×12",OGP("NANA","n_og_shift","B.shifts=3")+`return{d}`,r=>r.d===36);
T("10-15 紅玉の城：パーフェクト ×5（最大 50）・防御を無視",OGP("NANA","n_og_perf","G.st.perfect=(B.perf0||0)+4;B.e.block=30")+`return{d,eb:B.e.block}`,r=>r.d===20&&r.eb===30);
T("10-15 鳳凰戴天：最大ギアの外は半分",OGP("NANA","n_og_crown")+`return{d}`,r=>r.d===23||r.d===22);
T("10-15 1発の最終倍率は ×3 まで（ふつうは ×5）",SET("NANA",["n_og_crown","n_taikan"])+`B.gear=car().gears-1;B.rpm=1000;B.chain=12;B.nextBonus=5;const h0=B.e.hp;playCard(0,false);const og=h0-B.e.hp;return{og,cap:RULES.ogMultCap}`,r=>r.og<=Math.ceil(45*3)&&r.cap===3);
T("10-15 デッキ：奥義は1枚まで（OG1）・自分のキャラの奥義だけ",`const dk=defaultDeck("HINA");dk.h_og_rush=1;dk.h_og_pit=1;dk.slip=(dk.slip||0)-2;const e=deckErrors(dk,"HINA").join("/");const pool=deckPool("YUKI").filter(id=>CARDS[id].r==="OG");return{e,pool,own:pool.every(id=>CARDS[id].own==="YUKI")}`,r=>/奥義は1枚まで/.test(r.e)&&r.own&&r.pool.length===3);
T("10-15 報酬：ボス 3%・エリート 1%・ふつうは出ない（解放ずみ・自分のだけ）",`newRunState("MT","YUKI",[],null,{night:1});G.ul={cards:Object.keys(CARDS).filter(id=>CARDS[id].r!=="OG").concat(["y_og_frz","y_og_red","h_og_rush"]),parts:[]};const c={boss:0,elite:0,battle:0},n=6000;for(const r of ["boss","elite","battle"])for(let i=0;i<n;i++){if(rewardOptions(r).some(id=>CARDS[id].r==="OG"))c[r]++}
  const ids=new Set();for(let i=0;i<3000;i++)rewardOptions("boss").forEach(id=>{if(CARDS[id].r==="OG")ids.add(id)});return{b:c.boss/n,e:c.elite/n,n:c.battle,ids:[...ids]}`,r=>r.b>0.015&&r.b<0.05&&r.e>0.002&&r.e<0.025&&r.n===0&&r.ids.every(id=>["y_og_frz","y_og_red"].includes(id)));
T("10-15 ミニカーの10枚に奥義を入れない",`newRunState("MT","YUKI",[],null,{night:1});G.deck.push(inst("y_og_frz"));let k=0;for(let i=0;i<300;i++)if(mcTen().some(c=>c.id==="y_og_frz"))k++;return k`,r=>r===0);
T("10-16-1 天候：雨（チェイン +3%・芯 半分）／雪（凍結 ×1.5・帯 ×0.7）／得意は悪い所なし／ボスはドライ",`const R={};const go=(ch,wx)=>{newRunState("MT",ch,[],null,{night:1});const row=G.map[G.row],j=row.findIndex(n=>n.k==="battle");row[j].wx=wx;G.path[G.row]=j;startBattleState(nodeEnemy(row[j]))};
  go("YUKI","dry");const b0=bandRange(),c0=chainStep();go("YUKI","rain");const b1=bandRange();R.rc=Math.round((chainStep()-c0)*100);R.core=[b0.chi-b0.clo,b1.chi-b1.clo];R.band=[b0.hi-b0.lo,b1.hi-b1.lo];
  go("MOMO","dry");const m0=bandRange();go("MOMO","rain");const m1=bandRange();R.mfav=m0.chi-m0.clo===m1.chi-m1.clo;
  go("YUKI","snow");const y1=bandRange();R.yfav=y1.hi-y1.lo===b0.hi-b0.lo;let f0=B.frozeTotal;mkCtx(1).freeze(4);R.fz=B.frozeTotal-f0;
  go("HINA","dry");const h0=bandRange();go("HINA","snow");const h1=bandRange();R.hs=[h0.hi-h0.lo,h1.hi-h1.lo];
  let boss=0;for(let i=0;i<20;i++){newRunState("MT","YUKI",[],null,{night:1});G.map.flat().forEach(n=>{if(n.k==="boss"&&n.wx!=="dry")boss++})}R.boss=boss;return R`,r=>r.rc===3&&Math.abs(r.core[1]-r.core[0]/2)<=1&&r.band[0]===r.band[1]&&r.mfav&&r.yfav&&r.fz===6&&Math.abs(r.hs[1]-r.hs[0]*0.7)<=2&&r.boss===0);
T("10-18-1 第2形態の天候：体力 50% で変わる（残光 雨・白夜 雪・零号 霧・空転 雨・散花 霧・未決 夜明け）／霧＝シフトで防御 +2／夜明け＝レッド 500 下・敵の攻撃 +10%（HINA は効かない）",`const R={};const go=(ch,k)=>{newRunState("MT",ch,[],null,{night:1});startBattleState(k)};
  R.w=["boss1","boss2","boss3","kuuten","sanka","miketsu"].map(k=>{go("YUKI",k);const a=B.wx;B.e.hp=Math.floor(B.e.maxhp*0.5);checkPhase();return a+">"+B.wx});
  go("YUKI","boss1");B.e.hp=Math.floor(B.e.maxhp*0.6);checkPhase();R.early=B.wx;
  go("YUKI","boss3");B.wx="fog";const b0=B.block;onShiftUp("good");R.fogBlk=B.block-b0;
  go("YUKI","miketsu");const r0=redLo(),a0=eAtk(B.e,20);B.wx="dawn";R.red=r0-redLo();R.atk=[a0,eAtk(B.e,20)];
  go("HINA","miketsu");const h0=eAtk(B.e,20);B.wx="dawn";R.hina=[h0,eAtk(B.e,20)];return R`,r=>r.w.join()==="dry>rain,dry>snow,dry>fog,dry>rain,dry>fog,dry>dawn"&&r.early==="dry"&&r.fogBlk>=2&&r.red===500&&r.atk[1]===Math.round(r.atk[0]*1.1)&&r.hina[0]===r.hina[1]);
T("10-17 ヒートのレア度（design 24-6 で前の形）：0段 C60・R30・E10／2段 C48・R38・E14／5段 C30・R50・E20",`const H=RULES.heat,W=RULES.rarityW,f=h=>[W.C+H.rar[0]*h,W.R+H.rar[1]*h,W.E+H.rar[2]*h];return [f(0),f(2),f(5)]`,r=>JSON.stringify(r)==="[[60,30,10],[48,38,14],[30,50,20]]");
T("12-4 上の夜の得（design 24-4）：ログの夜のボーナス 1+0.2×(夜−1)（N1 ×1・N4 ×1.6・N11 ×3）",`const L=UNLOCK.log,f=n=>Math.round(Math.min(L.nightBonusMax,1+L.nightBonus*(n-1))*100)/100;return [f(1),f(2),f(4),f(6),f(11)]`,r=>JSON.stringify(r)==="[1,1.2,1.6,2,3]");
T("10-21 凍界・大日輪の1段（合成カードを持たせたランの測り）：凍界 24・凍結 3（強化 36・凍結 5）／大日輪 ×4",`const ty=CARDS.f_y_tokai,dn=CARDS.f_h_dainichirin;return [ty.v,ty.vu,kOf({id:"f_y_tokai"},false),kOf({id:"f_y_tokai"},true),descOf({id:"f_y_tokai",up:true},true,0),JSON.stringify(dn.fx),dn.d]`,r=>r[0]===28&&r[1]===42&&r[2]===3&&r[3]===5&&r[4].includes("凍結 5")&&r[4].includes("42")&&r[5].includes('["atkAtks",4]')&&r[6].includes("×4"));
T("10-21 氷華閃・緋翼の1段（v0.11.136）：氷華閃 凍結 2（強化 3）・ダメージ 12／18／緋翼 パーフェクトで ×1.5（強化しても ×1.5・四捨五入）",`const R={};newRunState("MT","NANA",[],null,{night:1});startBattleState("kei");B.e.hp=999;B.e.block=0;
  const go=(id,up,perf)=>{const c=inst(id);c.up=up;B.lastGrade=perf?"perfect":"good";const h0=B.e.hp,b0=B.block,x={attack:v=>{B.e.hp-=v},block:v=>{B.block+=v}};CD(c).fx.forEach(f=>{const op=OPS[f[0]];if(op&&f[0]==="perfBoth")op(x,...f.slice(1).map(a=>argOf(a,cardVal(c),kOf(c))))});return [h0-B.e.hp,B.block-b0]};
  R.h0=go("f_n_hiyoku",false,false);R.h1=go("f_n_hiyoku",false,true);R.h2=go("f_n_hiyoku",true,true);R.h3=go("f_n_hiyoku",true,false);R.k=[kOf({id:"f_y_hyoukasen"},false),kOf({id:"f_y_hyoukasen"},true),CARDS.f_y_hyoukasen.v,CARDS.f_y_hyoukasen.vu];return R`,r=>JSON.stringify(r.h0)==="[7,5]"&&JSON.stringify(r.h1)==="[11,8]"&&JSON.stringify(r.h2)==="[17,12]"&&JSON.stringify(r.h3)==="[11,8]"/* ★v0.22.167 強化で防御 8 */&&JSON.stringify(r.k)==="[2,3,12,18]");
T("10-21 v0.11.137 強化で数を ×1.5 にそろえる：灼雪 炎上 4→6／緋翼 防御 5→8／陽だまりグリップ 耐久 +2→+3・次のアタック +3→+5（文の {k}・{j}）",`const d=(id,up)=>descOf({id,up},up,0);return [d("f_y_shakusetsu",false),d("f_y_shakusetsu",true),d("f_n_hiyoku",true),d("f_h_hidamarigrip",false),d("f_h_hidamarigrip",true)]`,r=>r[0].includes("炎上 4")&&r[1].includes("炎上 6")&&r[2].includes("防御 8")&&r[3].includes("耐久 +2")&&r[3].includes("アタック +3")&&r[4].includes("耐久 +3")&&r[4].includes("アタック +5"));
T("陽だまりグリップを打つ：強化で耐久 +3・次の番のアタック +5",`newRunState("MT","HINA",[],null,{night:1});startBattleState("kei");G.hp=10;B.nextTurnAdd=0;const c=inst("f_h_hidamarigrip");c.up=true;B.hand=[c];B.rpm=1000;B.gas=9;playCard(0,false);return [G.hp,B.nextTurnAdd]`,r=>r[0]===13&&r[1]===5);
T("10-21 v0.11.139 凍界 28／42・大日輪 20／30（×4 はそのまま）",`return [CARDS.f_y_tokai.v,CARDS.f_y_tokai.vu,CARDS.f_h_dainichirin.v,CARDS.f_h_dainichirin.vu,JSON.stringify(CARDS.f_h_dainichirin.fx)]`,r=>r[0]===28&&r[1]===42&&r[2]===20&&r[3]===30&&r[4].includes('["atkAtks",4]'));
